use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    let mut left = Vec::new();
    let mut right = Vec::new();

    for line in input.as_array() {
        let mut row = Vec::new();
        for item in line.as_array() {
            row.push(item.as_i64().unwrap());
        }
        left.push(row);
    }

    for line in input.as_array() {
        let mut row = Vec::new();
        for item in line.as_array() {
            row.push(item.as_i64().unwrap());
        }
        right.push(row);
    }

    let mut common_keys = Vec::new();
    for (key, left_row) in left.iter().enumerate() {
        for (key, right_row) in right.iter().enumerate() {
            if left_row.iter().any(|&value| right_row.iter().any(|&value| value == value)) {
                common_keys.push((key, left_row.iter().min().unwrap(), right_row.iter().min().unwrap()));
            }
        }
    }

    common_keys.sort_by(|&(k1, l1, r1), &(k2, l2, r2)| {
        if l1 < l2 {
            return Ordering::Less;
        }
        if l2 < l1 {
            return Ordering::Greater;
        }
        if r1 < r2 {
            return Ordering::Less;
        }
        if r2 < r1 {
            return Ordering::Greater;
        }
        Ordering::Equal
    });

    let mut result = Vec::new();
    for (key, left_value, right_value) in common_keys {
        result.push(vec![key, left_value, right_value]);
    }

    serde_json::Value::Object(result)
}
